'use client';
import { useRef, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Avatar, Fold, Spin, Swap, useGrow } from '../lib/motion';
import { usePopover } from '../lib/popover';
import '../designme.css';
// its menus' rows glide in Clean
import '../lib/glide';
import './draft-review.css';

export interface DraftRecipient {
  name: string;
  initials?: string;
  /** The avatar's colour, like 'var(--dm-av-l)' */
  color?: string;
}

export interface DraftAttachment {
  name: string;
  /** Shown beside the name, like "240 KB" */
  size?: string;
  /** Still uploading: a spinner in place of the size */
  loading?: boolean;
}

export interface SendOption {
  /** `now` sends straight away; any other key schedules it */
  key: string;
  /** Like "Tomorrow at 09:00" */
  label: string;
  /** The quiet line under it in the menu */
  detail?: string;
}

/** draft (being checked), sending, undo (sent, with a window to take it back), sent, scheduled or discarded */
export type DraftPhase = 'draft' | 'sending' | 'undo' | 'sent' | 'scheduled' | 'discarded';

export interface DraftReviewProps {
  title?: string;
  /** The line under the title, like "After the pricing review with Maya" */
  subtitle?: string;
  to: DraftRecipient[];
  subject: string;
  onSubjectChange?: (subject: string) => void;
  /** The message as the agent wrote it. Paragraphs are split by blank lines. It stays editable; read edits from onBodyChange */
  body: string;
  onBodyChange?: (body: string) => void;
  attachments?: DraftAttachment[];
  /** A problem to settle before it sends, like an attachment the message mentions but nothing attached. It shows as a warning
      notice; the action marked `primary` is the one that settles it, in the warning tint, and the others are white */
  warning?: { text: ReactNode; actions: { label: string; onClick: () => void; primary?: boolean }[] };
  phase?: DraftPhase;
  /** When to send, picked from the menu beside the button */
  sendOptions?: SendOption[];
  sendOption?: string;
  defaultSendOption?: string;
  onSendOptionChange?: (key: string) => void;
  onSend?: (option: SendOption) => void;
  onDiscard?: () => void;
  /** Takes it back: undoes a send in its undo window, cancels a scheduled one, or brings back a discarded draft */
  onUndo?: () => void;
  /** Seconds left to undo, shown while the phase is undo */
  undoLeft?: number;
  labels?: { send?: string; schedule?: string; sending?: string; scheduling?: string; discard?: string; notSent?: string; sent?: string; scheduled?: string; delivered?: string; discarded?: string; nothingSent?: string; undo?: string; cancel?: string };
  className?: string;
}

/** A button whose words change (Send, Schedule, Sending) is as wide as its words and eases to its new width */
function useEaseWidth(key: unknown) {
  const ref = useRef<HTMLButtonElement>(null), w = useRef(0), was = useRef<HTMLElement | null>(null), reduce = useReducedMotion();
  useIsoLayoutEffect(() => {
    const b = ref.current; if (!b) return;
    const w1 = b.getBoundingClientRect().width, w0 = was.current === b ? w.current : 0, cs = getComputedStyle(b); w.current = w1; was.current = b;
    if (w0 && !reduce && Math.abs(w1 - w0) > .5) b.animate([{ width: w0 + 'px' }, { width: w1 + 'px' }], { duration: (parseFloat(cs.getPropertyValue('--dm-t')) || .34) * 1000, easing: cs.getPropertyValue('--dm-ease').trim() || 'ease' });
  }, [key]);
  return ref;
}

const WHEN: SendOption[] = [
  { key: 'now', label: 'Send now' },
  { key: 'tomorrow', label: 'Tomorrow at 09:00', detail: 'The start of their day' },
  { key: 'monday', label: 'Monday at 09:00', detail: 'The start of next week' }
];

/** An email the agent drafted, laid out like the email it is, to check and edit before it goes: send now or later, or
    discard it. A warning can stop it before it sends, and after sending there is a short window to undo. */
export function DraftReview({
  title = 'Draft from the agent', subtitle, to, subject, onSubjectChange, body, onBodyChange, attachments = [], warning, phase = 'draft',
  sendOptions = WHEN, sendOption, defaultSendOption, onSendOptionChange, onSend, onDiscard, onUndo, undoLeft = 5, labels = {}, className
}: DraftReviewProps) {
  const [pick, setPick] = useControllable(sendOption, defaultSendOption ?? sendOptions[0].key, onSendOptionChange);
  const menu = usePopover({ align: 'end' });
  const chosen = sendOptions.find(o => o.key === pick) ?? sendOptions[0];
  const later = chosen.key !== 'now';
  const L = { send: 'Send', schedule: 'Schedule', sending: 'Sending', scheduling: 'Scheduling', discard: 'Discard', notSent: 'Not sent', sent: 'Sent', scheduled: 'Scheduled', delivered: 'Delivered just now', discarded: 'Draft discarded', nothingSent: 'Nothing was sent', undo: 'Undo', cancel: 'Cancel', ...labels };
  const names = to.map(p => p.name).join(', ');
  // the body is written once and left to the browser while it is edited, so the caret stays where it is
  const first = useRef(body);
  const busy = phase === 'sending', done = phase !== 'draft' && phase !== 'sending';
  // no room is kept for what comes later: the card eases to its new height as the attachment, the warning or the result
  // arrives (as grow() on the site)
  const [root, inner] = useGrow();
  const goBtn = useEaseWidth(`${busy}:${later}`);
  const tag = phase === 'sent' ? ['dm-ok', L.sent] : phase === 'scheduled' ? ['dm-b', L.scheduled] : ['', L.notSent];
  const row = phase === 'undo' ? { icon: 'ok' as const, cls: '', t: `${L.sent} to ${names}`, sub: `You can undo for ${undoLeft}s`, btn: L.undo }
    : phase === 'sent' ? { icon: 'ok' as const, cls: '', t: `${L.sent} to ${names}`, sub: L.delivered }
    : phase === 'scheduled' ? { icon: 'clock' as const, cls: 'dm-later', t: `${L.scheduled} for ${chosen.label.replace(/^\w/, c => c.toLowerCase())}`, sub: `To ${names}`, btn: L.cancel }
    : phase === 'discarded' ? { icon: 'trash' as const, cls: 'dm-bin', t: L.discarded, sub: L.nothingSent, btn: L.undo } : null;

  return (
    <div data-dm="" className={className} style={{ width: '100%' }}>
      <div ref={root} className={cx('dm-drf dm-panel dm-growing', done && 'dm-sent')}>
        <div ref={inner} className="dm-grow">
        <div className="dm-drf-h">
          <span className="dm-drf-ag"><Icon name="spark" /></span>
          <div className="dm-drf-ht"><b>{title}</b>{subtitle && <span className="dm-muted">{subtitle}</span>}</div>
          <span className={cx('dm-tag dm-drf-tag', tag[0])}><Swap>{tag[1]}</Swap></span>
        </div>
        <div className="dm-drf-fs" inert={done}>
          <div className="dm-drf-r"><span className="dm-drf-l">To</span>
            {to.map(p => <span key={p.name} className="dm-drf-p"><Avatar initials={p.initials ?? p.name.split(' ').map(w => w[0]).join('').slice(0, 2)} color={p.color ?? 'var(--dm-av-l)'} />{p.name}</span>)}
          </div>
          <label className="dm-drf-r"><span className="dm-drf-l">Subject</span><input className="dm-drf-s" value={subject} onChange={e => onSubjectChange?.(e.target.value)} readOnly={!onSubjectChange} aria-label="Subject" /></label>
        </div>
        <div className="dm-drf-b" contentEditable={!done} suppressContentEditableWarning role="textbox" aria-multiline="true" aria-label="Message" spellCheck={false}
          style={{ whiteSpace: 'pre-wrap' }} inert={done} onInput={e => onBodyChange?.((e.target as HTMLElement).innerText)}>{first.current}</div>
        <div className="dm-drf-att" inert={done}>
          {attachments.map(a => (
            <span key={a.name} className="dm-drf-file dm-enter"><Icon name="file" size="xs" /><span>{a.name}</span>
              <span className="dm-muted dm-drf-fz">{a.loading ? <Spin /> : a.size}</span></span>
          ))}
        </div>
        <Fold open={!!warning && phase === 'draft'} className="dm-drf-wf">
          <div className="dm-drf-w" role="alert">
            <svg className="dm-drf-wi" viewBox="0 0 24 24" aria-hidden="true"><path className="dm-a" d="M12 3.6 2.6 19.9h18.8z" /><path className="dm-b" d="M12 9.6v4.4M12 17v.01" /></svg>
            <p>{warning?.text}</p>
            <div className="dm-drf-wa">
              {warning?.actions.map(a => <button key={a.label} type="button" className={cx('dm-pill dm-sm', a.primary ? 'dm-warn' : 'dm-ghost')} onClick={a.onClick}>{a.label}</button>)}
            </div>
          </div>
        </Fold>
        {row ? (
          <div className={cx('dm-drf-done dm-enter', row.cls)}>
            <span className="dm-g"><Icon name={row.icon} /></span>
            <span className="dm-t">{row.t}<span className="dm-muted dm-drf-sub">{row.sub}</span></span>
            {row.btn && <button type="button" className="dm-pill dm-sm" onClick={onUndo}>{row.btn}</button>}
          </div>
        ) : (
          <div className="dm-drf-f">
            <button type="button" className="dm-pill dm-ghost dm-sm dm-drf-x" disabled={busy} onClick={onDiscard}><Icon name="trash" size="xs" />{L.discard}</button>
            <span className="dm-sp" />
            <Swap className="dm-muted dm-drf-when">{later ? chosen.label : ''}</Swap>
            <div className="dm-drf-mg">
              <button ref={goBtn} type="button" className="dm-pill dm-primary dm-sm dm-drf-go" disabled={busy} onClick={() => onSend?.(chosen)}>
                {busy ? <><Spin />{later ? L.scheduling : L.sending}</> : <><Icon name={later ? 'clock' : 'send'} size="xs" />{later ? L.schedule : L.send}</>}
              </button>
              <button type="button" className="dm-pill dm-primary dm-sm dm-drf-dd" aria-label="When to send" disabled={busy} {...menu.trigger}><Icon name="chev-d" size="xs" /></button>
            </div>
            <div {...menu.pop} className={cx(menu.pop.className, 'dm-drf-pop')} role="menu" aria-label="When to send">
              {sendOptions.map(o => (
                <button type="button" key={o.key} className="dm-mi" role="menuitemradio" aria-checked={o.key === chosen.key} onClick={() => { setPick(o.key); menu.closeSoon(); }}>
                  <span>{o.label}{o.detail && <span className="dm-d">{o.detail}</span>}</span><span className="dm-ck"><Icon name="check" size="xs" /></span>
                </button>
              ))}
            </div>
          </div>
        )}
        </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Draft review ---------- */
/* what the agent wrote, laid out like the email it is: who it goes to, the subject, the message and what is attached,
   then send now or later, or discard. Before sending it checks for an attachment the message mentions, and after
   sending there is a short window to undo. The warning and the result sit on the head's columns (owner, 18 Nov): their mark
   centred under the head's tile, their words on the title's words, their buttons ending on the content's right edge, their
   tint reaching 8px out round them */
.dm-drf{position:relative;width:100%;max-width:440px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
/* Soft's card is plush: its content 20px in from every edge (owner, 22 Nov: "more padding inside"); Blueprint and Clean keep
   16px */
.dm-drf.dm-panel{padding:var(--dm-s-5)}
:root:not([data-style="soft"],[data-style="clean"]) .dm-drf.dm-panel:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){padding:var(--dm-s-4)}
.dm-drf-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.dm-drf-ag{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;flex:none}
.dm-drf-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-drf-ht b{font-weight:500;font-size:14px}
.dm-drf-ht span{font-size:13px}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.dm-drf :is(.dm-ib,.dm-pill):active{transform:none}
.dm-drf-fs{display:flex;flex-direction:column;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-drf-r{display:flex;align-items:center;gap:10px;min-height:40px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px}
.dm-drf-l{width:52px;flex:none;color:var(--dm-muted);font-size:13px}
.dm-drf-p{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px 0 3px;border-radius:var(--dm-r-pill);background:var(--dm-chip);font-size:13px}
.dm-drf-p .dm-av{width:20px;height:20px;font-size:9px}
.dm-drf-s{flex:1;min-width:0;height:38px;padding:0;border:0;background:none;outline:0;font:inherit;font-size:13.5px;color:var(--dm-fg)}
.dm-drf-r:has(.dm-drf-s:focus){border-bottom-color:color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-drf-b{font-size:14px;line-height:1.6;color:var(--dm-fg);outline:0;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)))}
.dm-drf-b:focus{box-shadow:0 0 0 6px var(--dm-surface),0 0 0 7px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-drf-att{display:flex;flex-wrap:wrap;gap:6px}
.dm-drf-att:empty{display:none}
.dm-drf-file{display:inline-flex;align-items:center;gap:var(--dm-s-2);height:30px;padding:0 10px;border-radius:var(--dm-r-sm);background:var(--dm-chip);font-size:13px}
.dm-drf-file>svg{color:var(--dm-fg2)}
.dm-drf-file .dm-muted{font-size:12px;display:inline-flex;align-items:center}
.dm-drf-file .dm-spin{width:10px;height:10px}
/* the shut warning is hidden once it has folded away, so nothing measures the clipped part as if it were drawn */
.dm-drf-wf.dm-shut>div{visibility:hidden;transition:visibility 0s var(--dm-t)}
/* a warning notice (owner, 18 Nov; Model picker's busy notice is the reference): a faint warning tint, the filled warning sign
   in the warning mark colour, the words in the text colour, the action that settles it in the warning tint (.pill.warn), and
   the other button white beside it */
.dm-drf-w{margin:0 calc(-1 * var(--dm-s-2));padding:var(--dm-s-3) var(--dm-s-2) var(--dm-s-2);border-radius:calc(var(--dm-r-card) - 8px);background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent);display:grid;grid-template-columns:32px minmax(0,1fr);align-items:start;column-gap:var(--dm-s-3);row-gap:var(--dm-s-2)}
.dm-drf-wi{grid-area:1/1;justify-self:center;width:16px;height:16px;margin-top:2px;overflow:visible}
.dm-drf-wi .dm-a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.dm-drf-wi .dm-b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.dm-drf-w p{grid-area:1/2;margin:0;font-size:13px;line-height:20px;color:var(--dm-fg)}
.dm-drf-wa{grid-area:2/1/3/3;display:flex;justify-content:flex-end;flex-wrap:wrap;gap:var(--dm-s-2)}
.dm-drf-w .dm-pill.dm-ghost{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.dm-drf-w .dm-pill.dm-ghost:hover{box-shadow:var(--dm-on-tint-btn-h)}}
/* no room is kept for what comes later (owner, 17 Nov): the card eases to its new height as the attachment, the warning or
   the result arrives (grow()); its menu opens out of it, and nothing changes height while the menu is open */
.dm-drf.dm-growing:has(.dm-drf-pop.dm-open){overflow:visible}
/* a hairline sets the buttons apart from the message, as in a mail composer */
.dm-drf-f{display:flex;align-items:center;gap:var(--dm-s-2);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-drf-f .dm-sp{flex:1}
.dm-drf-when{font-size:13px}
.dm-drf-mg{display:flex;gap:1px;flex:none}
.dm-drf-go{border-radius:var(--dm-r-pill) 0 0 var(--dm-r-pill);padding-right:var(--dm-s-3)}
.dm-drf-dd{border-radius:0 var(--dm-r-pill) var(--dm-r-pill) 0;padding:0 9px}
.dm-drf-pop{min-width:220px}
.dm-drf.dm-sent .dm-drf-fs,.dm-drf.dm-sent .dm-drf-b,.dm-drf.dm-sent .dm-drf-att{opacity:.55;transition:opacity .32s}
/* the result says what happened, so the head's tag steps aside while it shows (no row repeats what the card says) */
.dm-drf-tag{transition:opacity .32s var(--dm-ease)}
.dm-drf.dm-sent .dm-drf-tag{opacity:0}
/* sent, scheduled or discarded: a neutral row in the footer's place (owner, 18 Nov: a finished state has no green fill), its
   mark in the head tile's column (sent is the green tick) and its words on the title's, with a white button to take it back */
.dm-drf-done{display:flex;align-items:center;gap:var(--dm-s-3);margin:0 -8px;padding:8px;border-radius:calc(var(--dm-r-card) - 8px);background:var(--dm-chip);font-size:13.5px}
.dm-drf-done>.dm-g{width:32px;display:grid;place-items:center;flex:none;color:var(--dm-fg2)}
/* (on the grey row the tick takes the text green, as Permission gate's done row, so it keeps 3:1 on the grey) */
.dm-drf-done:not(.dm-bin,.dm-later)>.dm-g{color:var(--dm-ok)}
.dm-drf-done .dm-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-drf-done .dm-t span{font-size:13px}
.dm-drf-done .dm-t .dm-muted{color:var(--dm-fg2)}
.dm-drf-done .dm-pill{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.dm-drf-done .dm-pill:hover{box-shadow:var(--dm-on-tint-btn-h)}}
/* Clean (owner, 17 and 18 Nov): its content 16px from each edge; the buttons on the off-white foot strip, 8px from the card's
   edges, and the result in the strip's place, on one line, its mark under the head's tile */
:root[data-style="clean"] .dm-drf.dm-panel,:root [data-style="clean"] .dm-drf.dm-panel,:root [data-style="clean"].dm-drf.dm-panel{padding:16px}
:root[data-style="clean"] :is(.dm-drf-f,.dm-drf-done),:root [data-style="clean"] :is(.dm-drf-f,.dm-drf-done),:root [data-style="clean"]:is(.dm-drf-f,.dm-drf-done){margin:4px -16px -16px;padding:8px 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
/* (on a phone its words can take two lines: the strip grows with them, its mark and button staying on the words' centre line) */
:root[data-style="clean"] .dm-drf-done,:root [data-style="clean"] .dm-drf-done,:root [data-style="clean"].dm-drf-done{padding-left:16px;font-size:12.5px}
:root[data-style="clean"] :is(.dm-drf-done .dm-t span,.dm-drf-when),:root [data-style="clean"] :is(.dm-drf-done .dm-t span,.dm-drf-when),:root [data-style="clean"]:is(.dm-drf-done .dm-t span,.dm-drf-when){font-size:12.5px}
/* (a step of --dm-ok in the vivid green keeps the tick at 3:1 on the off-white strip, as Attachment tray's) */
:root[data-style="clean"] .dm-drf-done:not(.dm-bin,.dm-later)>.dm-g,:root [data-style="clean"] .dm-drf-done:not(.dm-bin,.dm-later)>.dm-g,:root [data-style="clean"].dm-drf-done:not(.dm-bin,.dm-later)>.dm-g{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
:root[data-style="clean"] .dm-drf-done .dm-t,:root [data-style="clean"] .dm-drf-done .dm-t,:root [data-style="clean"].dm-drf-done .dm-t{flex-direction:row;flex-wrap:wrap;align-items:baseline;column-gap:var(--dm-s-2);padding-block:4px;line-height:20px}
:root[data-style="clean"] .dm-drf-done .dm-t span,:root [data-style="clean"] .dm-drf-done .dm-t span,:root [data-style="clean"].dm-drf-done .dm-t span{color:var(--dm-muted)}
:root[data-style="clean"] .dm-drf-done .dm-pill,:root [data-style="clean"] .dm-drf-done .dm-pill,:root [data-style="clean"].dm-drf-done .dm-pill{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
