:root[data-style="clean"] .dm-drf-done .dm-pill:active,:root [data-style="clean"] .dm-drf-done .dm-pill:active,:root [data-style="clean"].dm-drf-done .dm-pill:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .dm-drf-w .dm-pill.dm-ghost,:root [data-style="clean"] .dm-drf-w .dm-pill.dm-ghost,:root [data-style="clean"].dm-drf-w .dm-pill.dm-ghost{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-drf-w .dm-pill.dm-ghost:hover,:root [data-style="clean"] .dm-drf-w .dm-pill.dm-ghost:hover,:root [data-style="clean"].dm-drf-w .dm-pill.dm-ghost:hover{box-shadow:var(--dm-btn2-hover)}}
