/* a pressed button never goes blank (owner, 18 Nov): the ink button turns to its disabled look at once, so its dark words never
   sit on a fill that is still fading in */
:root[data-style="clean"] :is(.dm-drf-go,.dm-drf-dd)[disabled],:root [data-style="clean"] :is(.dm-drf-go,.dm-drf-dd)[disabled],:root [data-style="clean"]:is(.dm-drf-go,.dm-drf-dd)[disabled]{transition:none}

